import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

selu_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256
#define ALPHA 1.67326324f
#define SCALE 1.05070098f

__global__ void selu_forward_kernel(const float* input, float* output, int num_elements) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        const float x = input[idx];
        output[idx] = x > 0 ? SCALE * x : SCALE * ALPHA * (expf(x) - 1);
    }
}

__global__ void selu_backward_kernel(const float* grad_output, const float* input, float* grad_input, int num_elements) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        const float x = input[idx];
        grad_input[idx] = grad_output[idx] * (x > 0 ? SCALE : SCALE * ALPHA * expf(x));
    }
}

torch::Tensor selu_forward(torch::Tensor x) {
    auto output = torch::empty_like(x);
    const int num_elements = x.numel();
    const dim3 blocks((num_elements + BLOCK_SIZE - 1) / BLOCK_SIZE);

    selu_forward_kernel<<<blocks, BLOCK_SIZE>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}

torch::Tensor selu_backward(torch::Tensor grad_output, torch::Tensor x) {
    auto grad_input = torch::empty_like(x);
    const int num_elements = x.numel();
    const dim3 blocks((num_elements + BLOCK_SIZE - 1) / BLOCK_SIZE);

    selu_backward_kernel<<<blocks, BLOCK_SIZE>>>(
        grad_output.data_ptr<float>(),
        x.data_ptr<float>(),
        grad_input.data_ptr<float>(),
        num_elements
    );

    return grad_input;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &selu_forward, "SELU forward");
    m.def("backward", &selu_backward, "SELU backward");
}
"""

selu_module = load_inline(
    name='selu_module',
    cuda_sources=selu_cuda_source,
    extra_cuda_cflags=["-O3"]
)

class SELUFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.save_for_backward(x)
        return selu_module.forward(x)

    @staticmethod
    def backward(ctx, grad_output):
        x, = ctx.saved_tensors
        return selu_module.backward(grad_output, x)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        return SELUFunction.apply(x)
